  keyPoints: string[];
  prerequisites: string[];
  theory: string[];
  equation: string;
  calculationExample: string;
  procedure: string[];
  observations: { columns: string[]; rows: string[][]; note: string };
  precautions: string[];
  conclusion: string;
  assumptions: string[];
  references: string[];
